#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    int intersectionSizeTwo(vector<vector<int>>& intervals) {
        sort(intervals.begin(), intervals.end(), [](auto& a, auto& b) {
            return a[1] != b[1] ? a[1] < b[1] : a[0] > b[0];
        });

        int res = 0, a = -1, b = -1;
        for (auto& it : intervals) {
            if (it[0] > b) {
                res += 2;
                b = it[1];
                a = it[1] - 1;
            } else if (it[0] > a) {
                res += 1;
                a = b;
                b = it[1];
            }
        }
        return res;
    }
};
